repo.harvests.py:
"""Harvest records."""


class Harvest:
    def __init__(self, field, kilos):
        self.field = field
        self.kilos = kilos

    def __repr__(self):
        return "Harvest(%r, %r)" % (self.field, self.kilos)


ROWS = [('upper', 39), ('upper', 32), ('hill', 49), ('hill', 3), ('lower', 37), ('upper', 15)]


def load_harvests():
    """Yield the stored harvests one at a time."""
    for field, kilos in ROWS:
        yield Harvest(field, kilos)

repo.summary.py:
"""Summary of harvests."""


class HarvestSummary:
    def __init__(self, harvests):
        self._harvests = harvests

    def count(self):
        """Return how many harvests there are."""
        return sum(1 for _ in self._harvests)

    def mean_kilos(self):
        """Return the mean kilos, or 0.0 when there are no harvests."""
        total = sum(x.kilos for x in self._harvests)
        n = self.count()
        return total / n if n else 0.0


def field_names(harvests):
    """Return the distinct field values, in first-seen order."""
    names = []
    for x in harvests:
        if x.field not in names:
            names.append(x.field)
    return names
